import { defineConfig } from "@playwright/test";

const port = Number(process.env.RELAYVIEW_BROWSER_PORT ?? 4175);
const projectRoot = new URL("..", import.meta.url).pathname;

export default defineConfig({
  testDir: new URL("./e2e", import.meta.url).pathname,
  testMatch: "*.e2e.ts",
  timeout: 30_000,
  use: {
    baseURL: `http://127.0.0.1:${port}`,
    browserName: "chromium",
    viewport: { width: 1440, height: 960 }
  },
  webServer: {
    command: "npm run build && RELAYVIEW_BROWSER_FIXTURE=1 npm exec vite preview -- --config browser/vite.config.ts",
    cwd: projectRoot,
    port,
    reuseExistingServer: false,
    timeout: 30_000
  }
});

